def solve():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    for s in input[1:t+1]:
        count_A = s.count('A')
        count_C = s.count('C')
        count_B = s.count('B')
        if count_A == count_C and count_B >= abs(count_A - count_C):
            print("YES")
        else:
            print("NO")

solve()
